#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, mod;
    cin >> n >> m >> mod;

    const int MAX_SIZE = 505;
    int C[MAX_SIZE][MAX_SIZE] = {0};
    int way[MAX_SIZE] = {0};
    int sum[MAX_SIZE] = {0};
    int g[MAX_SIZE][MAX_SIZE] = {0}, f[MAX_SIZE][MAX_SIZE] = {0};

    auto add_mod = [&](int a, int b) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    };

    auto multiply_mod = [&](int a, int b) {
        return (long long)a * b % mod;
    };

    auto triangle_sum = [&](int i) {
        return i * (i + 1) / 2;
    };

    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = add_mod(C[i - 1][j - 1], C[i - 1][j]);
        }
    }

    way[0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            way[i] = add_mod(way[i], multiply_mod(multiply(i + 1, C[i - 1][j]), multiply_mod(way[j], way[i - j - 1])));
            sum[i] = add_mod(sum[i], multiply_mod(multiply(triangle_sum(j), way[j]), way[i - j - 1]));
            sum[i] = add_mod(sum[i], multiply_mod(multiply(i + 1, add_mod(multiply(sum[j], way[i - j - 1]), multiply(way[j], sum[i - j - 1]))), C[i - 1][j]));
        }
    }

    n += 1;
    f[0][0] = 1;
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                int val_f = multiply_mod(f[i][j], way[k]);
                f[i + k + 1][j + k] = add_mod(f[i + k + 1][j + k], val_f);
                int val_g = add_mod(multiply_mod(val_f, sum[k]), multiply_mod(g[i][j], way[k]));
                g[i + k + 1][j + k] = add_mod(g[i + k + 1][j + k], val_g);
            }
        }
    }

    cout << g[n][m] << "\n";
    return 0;
}
